func TestZZMeasure(t *testing.T) {
	after := shippedThemes(t)
	names := []string{}
	for n := range after {
		names = append(names, n)
	}
	sort.Strings(names)
	f, _ := os.Create(os.Getenv("M_OUT"))
	defer f.Close()
	for _, n := range names {
		before := &Theme{}
		if n == "default" {
			*before = *DefaultTheme()
			before.SeverityLow, before.SeverityLowFg = "#585b70", "#cdd6f4"
		} else {
			out, err := exec.Command("git", "show", "HEAD:themes/"+n+".json").Output()
			if err != nil {
				t.Fatal(err)
			}
			if err := json.Unmarshal(out, before); err != nil {
				t.Fatal(err)
			}
		}
		for i, th := range []*Theme{before, after[n]} {
			ApplyTheme(DefaultTheme())
			ApplyTheme(th)
			r := func(a, b color.Color) float64 { x, _ := ContrastRatio(a, b); return x }
			d, _ := ColorDistance(ColorSeverityCritical, ColorSeverityHigh)
			rail := GaugeTrackStyle().GetForeground()
			if i == 0 {
				rail = ColorSeverityLow
			}
