				Hex(ColorSeverityLow), Hex(ColorSeverityLowFg), r(ColorSeverityLowFg, ColorSeverityLow), r(ColorSeverityLow, ColorBackground), r(ColorSeverityLow, ColorTableLineSelected),
				Hex(rail), r(rail, ColorBackground), r(rail, ColorTableLineSelected))
		}
	}
}
